<template>
  <div style="height: 100vh;" class="mt-2">
    <div id="reportContainer" style="height: calc(100vh - 40px); width: 100%;"></div>
  </div>
</template>

<script>
import * as powerbi from 'powerbi-client'
import DataService from '../../services/DataService';
const envType = process.env.VUE_APP_NODE_ENV;
export default {
  name: 'StagingBillingDashboard',

  methods: {
    async loadPowerBIReport() {
      try {
        // Use DynamicEmbedReport for staging with moduleId 4 (Billing)
        var moduleName='Billing';
        var environment=envType;
        const response = await DataService.DynamicEmbedReport(moduleName, environment);
        
        if (!response || response.status !== 200) {
          throw new Error('Failed to fetch embed config');
        }

        const embedData = response.data;

        // Basic validations
        if (!embedData.reportId) throw new Error('Report ID is missing');
        if (!embedData.embedUrl) throw new Error('Embed URL is missing');
        if (!embedData.embedToken) throw new Error('Embed token is missing');
        if (!embedData.companyId) throw new Error('Company ID is missing');

        const companyId = embedData.companyId;
        const tablesToFilter = embedData.tables;

        // Create filters dynamically from table configurations
        let filters = [];
        // const filters = tablesToFilter
        //   .filter(tableConfig => tableConfig.filterColumn && tableConfig.filterColumn.trim() !== '')
        //   .map(tableConfig => ({
        //     $schema: "http://powerbi.com/product/schema#basic",
        //     target: {
        //       table: tableConfig.tableName,
        //       column: tableConfig.filterColumn
        //     },
        //     operator: "In",
        //     values: [companyId],
        //     filterType: powerbi.models.FilterType.BasicFilter
        //   }));

        const compnayFilters = {
            $schema: "http://powerbi.com/product/schema#basic",
            target: {
              table: "TALYGEN_company",          // 🔸 Table name in your Power BI model (case-sensitive)
              column: "company_id"       // 🔸 Column used in slicer & relationships
            },
            operator: "In",
            values: [companyId],
            filterType: powerbi.models.FilterType.BasicFilter
          };

        filters.push(compnayFilters)

        console.log('Staging Report Filters: ', filters);

        const embedConfig = {
          type: 'report',
          id: embedData.reportId,
          embedUrl: embedData.embedUrl,
          accessToken: embedData.embedToken,
          tokenType: powerbi.models.TokenType.Embed,
          filters: filters,
          settings: {
            panes: {
              filters: { visible: false },
              pageNavigation: { visible: true }
            }
          }
        };

        const reportContainer = document.getElementById('reportContainer');

        // Embed the report
        const powerbiService = new powerbi.service.Service(
          powerbi.factories.hpmFactory,
          powerbi.factories.wpmpFactory,
          powerbi.factories.routerFactory
        );

        const report = powerbiService.embed(reportContainer, embedConfig);

        // Optional: re-apply filter if needed after load
        report.on('loaded', async () => {
          try {
            await report.setFilters(filters);
            console.log("✅ Staging Power BI report embedded successfully");
          } catch (filterErr) {
            console.error('Error applying filters after load:', filterErr);
          }
        });

        report.on('error', (event) => {
          console.error('Staging Report Error:', event.detail);
        });

      } catch (err) {
        console.error('❌ Staging Power BI embed error:', err);
      }
    }
  },

  mounted() {
    this.loadPowerBIReport()
  }
}
</script>